#!/usr/bin/env python3
"""Build an image-first directory of precisely mapped, credited site photographs."""
import json,html
from pathlib import Path
from urllib.parse import quote
R=Path(__file__).resolve().parent.parent
E=lambda x:html.escape(str(x),quote=True)
photos=json.loads((R/'data/site-photos.json').read_text());sites={s['n']:s for s in json.loads((R/'data/sites.json').read_text())};videos=json.loads((R/'data/videos.json').read_text())
body=''
for name,ps in sorted(photos.items()):
 p=ps[0];island=p.get('collection') or ('Corsica' if '(Corsica)' in name else 'Sardinia');url='/?site='+quote(name,safe='');body+=f'<article class="photo" data-island="{island}" data-photo-only="{str(not bool(videos.get(name))).lower()}"><a href="{url}"><img src="{E(p["image"])}" alt="{E(p["caption"])}" width="{p["width"]}" height="{p["height"]}" loading="lazy"></a><div style="padding:20px"><div class="eyebrow">{island} · {len(ps)} photographs</div><h3><a href="{url}">{E(name)}</a></h3><div class="credit">{E(p["author"])} · <a href="{E(p["license_url"])}">{E(p["license"])}</a> · <a href="{E(p["source"])}">Commons ↗</a></div><a href="{url}">Explore the mapped site →</a></div></article>'
collections=list(dict.fromkeys(p[0].get('collection') or ('Corsica' if '(Corsica)' in n else 'Sardinia') for n,p in photos.items()))
filter_buttons=''.join(f'<button data-filter="{E(c)}" aria-pressed="false">{E(c)}</button>' for c in collections)
text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ancient sites in photographs | The Ancient Atlas</title><meta name="description" content="Explore major monuments and less familiar stonework in credited photographs. Credited photographs linked to precise map sites."><link rel="canonical" href="https://theancientatlas.com/photos/"><link rel="stylesheet" href="/assets/island-guides.css"><link rel="icon" href="/favicon.ico"><script defer src="/assets/js/analytics.js"></script><style>.photo img{{height:250px;object-fit:contain;background:#08090c}}.controls{{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}}button[aria-pressed=true]{{background:#C9A84C;color:#0B0B0F}}</style></head><body><header><a class="brand" href="/"><img src="/icon-256.png" alt="">The Ancient Atlas</a><nav><a href="/">Map</a><a href="/islands/">Island guides</a><a href="/creators/">Creators</a></nav></header><main><section style="border:0"><div class="eyebrow">Visual field guides</div><h1>Follow the stone.</h1><p class="lede">Great monuments. Quiet discoveries. Every photograph belongs to a specific place on the map.</p><div class="controls" hidden><button data-filter="All" aria-pressed="true">All sites</button>{filter_buttons}<button data-filter="photo-only" aria-pressed="false">Places without films</button></div><p role="status" aria-live="polite">{len(photos)} sites · {sum(map(len,photos.values()))} photographs</p><div class="grid">{body}</div></section></main><footer>Each photograph retains its stated licence. Photographer, licence and Commons source accompany every image. Web versions preserve the full composition, resized and converted to WebP.<br><a href="/data/site-photos.json">Full image credits</a> · <a href="/contact.html">Suggest a correction</a></footer><script>const cards=[...document.querySelectorAll('[data-island]')],buttons=[...document.querySelectorAll('[data-filter]')];document.querySelector('.controls').hidden=false;buttons.forEach(b=>b.addEventListener('click',()=>{{buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));cards.forEach(x=>x.hidden=b.dataset.filter==='photo-only'?x.dataset.photoOnly!=='true':b.dataset.filter!=='All'&&x.dataset.island!==b.dataset.filter);document.querySelector('[role=status]').textContent=cards.filter(x=>!x.hidden).length+' sites shown';}}));const selected=new URLSearchParams(location.search).get('region');if(selected)buttons.find(b=>b.dataset.filter===selected)?.click();</script></body></html>'''
O=R/'public/photos';O.mkdir(exist_ok=True);(O/'index.html').write_text(text)
print('Built photographic site directory')
